          "raw_ref": "9ee562b0ef19fb09"
        }
      ]
    }
  ],
  "self_assessment": 0.4,
  "proposed_subquestions": [
    {
      "text": "JECFA 96차 회의 공식 요약보고서(WHO 원문, 영어) 전문을 직접 fetch하여 발암성 근거 평가 관련 원문 문장을 확인할 수 있는가?",
      "value_est": 0.9
